  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_CFD_PNF_ID_COUNT) && (gen_idx < LPARA_CFD_PNF_ID_MAX_COUNT); gen_idx++) begin : gen_cfd_pnf_id_we_decode
