      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

