      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_rd_req),
        .o_q         (w_rd_req_reg)
      );
