        if (!i_rst_n_reg)
          reg_wr_req_reg_dly <= 1'b0;
        else
          reg_wr_req_reg_dly <= w_wr_req_reg;
      end
      assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
      assign w_wr_ack = reg_wr_req_reg_dly;

