          w_rdata_nxt = w_cfd_pnf_dm1_value[3];
      end
      (LPARA_CFD_PNF_DM1_BASE_OFFSET + (32'd4 * LPARA_CFD_PNF_DM1_OFFSET_STRIDE)): begin
        if ((PARA_CFD_PNF_DM1_COUNT > 32'd4) && (PARA_CFD_PNF_DM1_COUNT <= LPARA_CFD_PNF_DM1_MAX_COUNT))
          w_rdata_nxt = w_cfd_pnf_dm1_value[4];
      end
      (LPARA_CFD_PNF_DM1_BASE_OFFSET + (32'd5 * LPARA_CFD_PNF_DM1_OFFSET_STRIDE)): begin
        if ((PARA_CFD_PNF_DM1_COUNT > 32'd5) && (PARA_CFD_PNF_DM1_COUNT <= LPARA_CFD_PNF_DM1_MAX_COUNT))
          w_rdata_nxt = w_cfd_pnf_dm1_value[5];
      end
      (LPARA_CFD_PNF_DM1_BASE_OFFSET + (32'd6 * LPARA_CFD_PNF_DM1_OFFSET_STRIDE)): begin
        if ((PARA_CFD_PNF_DM1_COUNT > 32'd6) && (PARA_CFD_PNF_DM1_COUNT <= LPARA_CFD_PNF_DM1_MAX_COUNT))
          w_rdata_nxt = w_cfd_pnf_dm1_value[6];
      end
      (LPARA_CFD_PNF_DM1_BASE_OFFSET + (32'd7 * LPARA_CFD_PNF_DM1_OFFSET_STRIDE)): begin
        if ((PARA_CFD_PNF_DM1_COUNT > 32'd7) && (PARA_CFD_PNF_DM1_COUNT <= LPARA_CFD_PNF_DM1_MAX_COUNT))
          w_rdata_nxt = w_cfd_pnf_dm1_value[7];
      end
      LPARA_CFD_TT_CFG_OFFSET: w_rdata_nxt = w_cfd_tt_cfg_value;
      LPARA_CFD_TT_REF_OFFSET: w_rdata_nxt = w_cfd_tt_ref_value;
      LPARA_CFD_TT_TURN_OFFSET: w_rdata_nxt = w_cfd_tt_turn_value;
      LPARA_CFD_TT_TURD_OFFSET: w_rdata_nxt = w_cfd_tt_turd_value;
      LPARA_CFD_TT_MTX_OFFSET: w_rdata_nxt = w_cfd_tt_mtx_value;
      LPARA_CFD_TT_WD_OFFSET: w_rdata_nxt = w_cfd_tt_wd_value;
      LPARA_CFD_TT_STS_OFFSET: w_rdata_nxt = w_cfd_tt_sts_value;
      LPARA_CFD_TT_CTIME_OFFSET: w_rdata_nxt = w_cfd_tt_ctime_value;
      LPARA_CFD_TT_GTIME_OFFSET: w_rdata_nxt = w_cfd_tt_gtime_value;
      LPARA_CFD_TT_LTIME_OFFSET: w_rdata_nxt = w_cfd_tt_ltime_value;
      LPARA_CFD_TT_SWT_OFFSET: w_rdata_nxt = w_cfd_tt_swt_value;
      LPARA_CFD_TT_TMARK_OFFSET: w_rdata_nxt = w_cfd_tt_tmark_value;
      LPARA_CFD_TT_CLK_OFFSET: w_rdata_nxt = w_cfd_tt_clk_value;
      LPARA_CFD_TT_GPRE_OFFSET: w_rdata_nxt = w_cfd_tt_gpre_value;
      LPARA_CFD_TT_GAP_OFFSET: w_rdata_nxt = w_cfd_tt_gap_value;
      LPARA_CFD_TTB_PER_OFFSET: w_rdata_nxt = w_cfd_ttb_per_value;
