      LPARA_CFD_TTR_MISS0_OFFSET: w_rdata_nxt = w_cfd_ttr_miss0_value;
      LPARA_CFD_TTR_MISS1_OFFSET: w_rdata_nxt = w_cfd_ttr_miss1_value;
