      LPARA_CFD_TTIRQ_INJ_OFFSET: w_rdata_nxt = w_cfd_ttirq_inj_value;
      LPARA_CFD_TTIRQ_STS_OFFSET: w_rdata_nxt = w_cfd_ttirq_sts_value;
